style.css:
@-moz-document domain("roblox.com") {
/* PAGE BACKGROUND */
html,
body {
    background: #dfc5fa !important;
    min-height: 100% !important;
}

/* ACTUAL ROBLOX CONTENT BACKGROUND */
div#content.content {
    background-color: #dfc5fa !important;
    background-image: url("https://i.postimg.cc/cJfjs1DC/wp10236566.jpg") !important;
    background-position: center top !important;
    background-repeat: no-repeat !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    min-height: 100vh !important;
}

/* REMOVE SOLID BACKGROUNDS FROM MAIN WRAPPERS */
#wrap,
#container-main,
.main-content {
    background-color: transparent !important;
}

/* CUTE HEADINGS */
h1, h2, h3, h4 {
    color: #a36cbd !important;
    font-family: "Trebuchet MS", sans-serif !important;
}

/* PINK BUTTONS */
button,
.btn-primary,
.btn-common {
    background-color: #f5c9e9 !important;
    color: #87558f !important;
    border: 1px solid #e8b0df !important;
    border-radius: 15px !important;
}

/* CUTE LINKS */
a {
    color: #b56fbd !important;
}

/* LAVENDER SCROLLBAR */
::-webkit-scrollbar-thumb {
    background: #c99be8 !important;
    border-radius: 20px !important;
}
}
